 }else if(screen==='"'pending'){
 content="'`<div class="status-symbol" aria-hidden="true">↗</div><p class="eyebrow">Handover sent</p><h1>Waiting for Priya.</h1><p class="muted">Your request is ready for Priya Raman.</p><div class="transfer"><div><strong>Jamie Ellis</strong><small>Responsible now</small></div><span aria-hidden="true">→</span><div><strong>Priya Raman</strong><small>Not yet accepted</small></div></div><div class="note"><strong>You’re still responsible.</strong><br>Keep covering ${m.rotation} until the handover is accepted.</div><button id="withdraw" class="full">Cancel request</button><p class="muted tiny" style="margin-top:var(--s5)">Acceptance can be recorded here for this local handover.</p><button id="accept" class="text-button full">Record Priya’s acceptance</button>`;foot='"'Request pending · responsibility stays with Jamie';
