 }else{
 content="'`<div class="blank"><p class="eyebrow">Your schedule</p><h1>No shifts scheduled.</h1><p class="muted">There’s no on-call schedule to show. A schedule owner can add your next rotation.</p></div><button id="return" class="full">Back</button>`;foot='"'No schedule available';
 }
 app.innerHTML="'`<header class="menu-header"><span class="rota-brand"><span class="rota-mark" aria-hidden="true"></span>${m.product}</span><span class="muted">On call</span></header><section class="menu-content">${content}</section><footer class="menu-footer">${foot}</footer>`;
