 action('"'handover',()=>{review=false;go('compose');});action('cancel',()=>{review=false;go('main');});action('review',()=>{handoverNote=document.getElementById('handover-note').value;review=true;renderMenu();app.querySelector('h1').tabIndex=-1;app.querySelector('h1').focus();});action('edit',()=>{review=false;renderMenu();document.getElementById('handover-note').focus();});action('send',()=>go('pending'));action('withdraw',()=>go('main'));action('accept',()=>go('accepted'));action('return',()=>go('main'));
