 else if(done)content=`<div class="welcome-graphic"><div class="status-symbol" aria-hidden="true">✓</div></div><p class="eyebrow">Setup complete</p><h1>You’re ready,<br>${esc(bankName.split('"' ')[0])}.</h1><p class=\"intro\">Your mobile number is verified.</p><section class=\"account-summary\" aria-label=\"Your account\"><h2 style=\"font-size:var(--fs-xl)\">"'${b.accountName}</h2><p class="balance">${b.balance}</p><p class="hint">Available balance</p><dl><div><dt>Sort code</dt><dd>${b.sortCode}</dd></div><div><dt>Account number</dt><dd>${b.accountNumber}</dd></div></dl></section><p class="completion-note">Keep your account details private. You can get help any time using Help above.</p>`;
 else content=`<p class="bank-step">Step 2 of 2 · Security check</p><h1>Check your<br>text messages.</h1><p class="intro">Enter the ${b.codeLength}-digit code sent to your mobile ending <strong>${esc(bankMobile?bankMobile.slice(-3):b.mobileEnding)}</strong>.</p><form class="bank-form" id="code-form" novalidate><div><label for="security-code">Security code</label><input class="code-input" id="security-code" inputmode="numeric" pattern="[0-9]*" autocomplete="one-time-code" maxlength="6" aria-describedby="code-hint code-error" ${screen==='"'code-error'?'aria-invalid=\"true\"':''}><p id=\"code-hint\" class=\"hint\">Enter all "'${b.codeLength} digits from the text message.</p><p id="code-error" class="error" ${screen==='"'code-error'?'':'hidden'}>That code doesn’t match. Check the text message and try again.</p></div><button class=\"primary full\" type=\"submit\">Verify and finish →</button></form><div class=\"bank-actions\"><button id=\"resend\">Send a new code</button><button id=\"back\" class=\"text-button\">Back to your details</button></div><p id=\"resend-status\" class=\"hint\" role=\"status\"></p>"'`;
 app.innerHTML=`<header class="bank-header"><div class="bank-brand">${harbour}${b.name}</div><button id="help-button" aria-haspopup="dialog">Help</button></header><section>${content}</section>${safety()}<dialog id="help-dialog" aria-labelledby="help-title" aria-describedby="help-description"><h2 id="help-title">Talk to a person.</h2><p id="help-description">If you’re stuck, our support team can help you set up your account.</p><a class="help-phone" href="tel:${b.helpPhone.replaceAll('"' ','')}\">"'${b.helpPhone}</a><p class="hint">Freephone from UK landlines and mobiles.</p><p>${b.warning}</p><button id="close-help" class="primary full">Back to setup</button></dialog>`;
 const help=document.getElementById('"'help-button'),dialog=document.getElementById('help-dialog');let returnFocus=help;
 help.onclick=()=>{returnFocus=document.activeElement;dialog.showModal();};document.getElementById('close-help').onclick=()=>dialog.close();dialog.addEventListener('close',()=>returnFocus.focus());
 if(screen==='help'){dialog.showModal();}
 document.getElementById('start')?.addEventListener('click',()=>go('details'));
 document.getElementById('back')?.addEventListener('click',()=>go(details?'welcome':'details'));
 document.getElementById('details-form')?.addEventListener('submit',e=>{e.preventDefault();const name=document.getElementById('full-name'),mobile=document.getElementById('mobile');const validName=name.value.trim().split(/\\s+/).length>=2&&name.value.trim().length>2;const validMobile=/"'^(07'"\\d{9}|\\+447\\d{9}|447\\d{9})"'$/.test(mobile.value.replace(/['"\\s()-]/g,''));for(const [el,valid,error] of [[name,validName,'name-error'],[mobile,validMobile,'mobile-error']]){el.setAttribute('aria-invalid',String("'!valid));document.getElementById(error).hidden=valid;}if(!validName||!validMobile){(!validName?name:mobile).focus();return;}bankName=name.value.trim();bankMobile=mobile.value.replace(/['"\\s()-]/g,'');go('code');});
 document.getElementById('code-form')?.addEventListener('submit',e=>{e.preventDefault();const input=document.getElementById('security-code');if(input.value.trim()===b.testCode){go('done');}else{document.getElementById('code-error').hidden=false;input.setAttribute('aria-invalid','true');input.focus();input.select();}});
 document.getElementById('resend')?.addEventListener('click',()=>{document.getElementById('resend-status').textContent='A new code has been requested. Delivery is unavailable in this offline preview.';});
}
render();
EOF"

